fn_seat_change_syncs_seat_first_count.definition:
CREATE OR REPLACE FUNCTION public.fn_seat_change_syncs_seat_first_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_table_id uuid;
  v_tid uuid;
BEGIN
  v_table_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.table_id ELSE NEW.table_id END;
  IF v_table_id IS NULL THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  SELECT tournament_id INTO v_tid
    FROM public.tables
   WHERE id = v_table_id;
  IF v_tid IS NULL THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.tournaments t
     WHERE t.id = v_tid
       AND public.fn_ca_tournament_recorded_seat_first(t.id, true)
  ) THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  PERFORM public.fn_sync_seat_first_player_count(v_tid);
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

fn_sync_seat_first_player_count.definition:
CREATE OR REPLACE FUNCTION public.fn_sync_seat_first_player_count(p_tournament_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_table      uuid;
  v_seats      integer := 0;
  v_seat_first boolean := false;
  v_is_spin    boolean := false;
  v_cap        integer := 0;
  v_variant    text := '';
  v_book       jsonb;
BEGIN
  -- This is an AFTER-seat helper. It must never acquire a new global lock
  -- after PostgreSQL already owns the changed seat row. Every legitimate
  -- create/revive root pre-acquires terminal -> mission -> launch -> tournament,
  -- and the earliest BEFORE trigger refuses a raw writer that did not.
  SELECT public.fn_ca_tournament_recorded_seat_first(t.id, true),
         t.format_contract = 'spin-v1',
         COALESCE(t.max_players, 0),
         COALESCE(t.variant, '')
    INTO v_seat_first, v_is_spin, v_cap, v_variant
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Freeze the complete table/seat set before choosing the occupied table.
  -- UUID order is deterministic across every transaction using this owner.
  PERFORM tb.id
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
     AND lower(COALESCE(tb.status, '')) <> 'closed'
   ORDER BY tb.id
   FOR UPDATE;

  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id
     AND lower(COALESCE(tb.status, '')) <> 'closed'
     AND s.left_at IS NULL
   ORDER BY s.table_id, s.seat_number, s.id
   FOR UPDATE OF s;

  v_table := public.fn_tournament_primary_table(p_tournament_id);

  IF v_table IS NULL THEN
    IF COALESCE(v_seat_first, false) THEN
      SELECT count(*) INTO v_seats
        FROM public.table_seats s
        JOIN public.tables tb ON tb.id = s.table_id
       WHERE tb.tournament_id = p_tournament_id
         AND s.left_at IS NULL;
      UPDATE public.tournaments SET current_players = v_seats
       WHERE id = p_tournament_id
         AND current_players IS DISTINCT FROM v_seats;
      RETURN v_seats;
    END IF;
    RETURN NULL;
  END IF;

  SELECT count(*) INTO v_seats
    FROM public.table_seats
   WHERE table_id = v_table AND left_at IS NULL;

  UPDATE public.tables SET current_players = v_seats
   WHERE id = v_table
     AND current_players IS DISTINCT FROM v_seats;

  IF COALESCE(v_seat_first, false) THEN
    UPDATE public.tournaments SET current_players = v_seats
     WHERE id = p_tournament_id
       AND current_players IS DISTINCT FROM v_seats;
  END IF;

  -- DIAMOND PHASE 9: a Diamond Spin's three entries are already whole in
  -- custody; its reserve legs are booked at its draw, against its source.
  IF v_is_spin AND v_cap > 0 AND v_seats >= v_cap
     AND NOT public.fn_poker_diamond_tournament(p_tournament_id) THEN
    v_book := public.fn_spin_book_entry(p_tournament_id);
    IF COALESCE((v_book->>'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'paid third seat could not book Spin %: %',
        p_tournament_id,v_book USING ERRCODE = 'P0404';
    END IF;
  END IF;

  IF COALESCE(v_seat_first, false)
     AND v_cap > 0 AND v_seats >= v_cap THEN
    BEGIN
      PERFORM realtime.send(
        jsonb_build_object(
          'tournament_id', p_tournament_id,
          'variant', v_variant,
          'max_players', v_cap,
          'paid_seats', v_seats,
          'filled_at', now()
        ),
        'seat_first_ready',
        'seat_first',
        false
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING
        'fn_sync_seat_first_player_count: realtime.send failed for %: %',
        p_tournament_id, SQLERRM;
    END;
  END IF;

  RETURN v_seats;
END;
$function$

allocate_lifetime_vip_diamond_spend.definition:
CREATE OR REPLACE FUNCTION public.allocate_lifetime_vip_diamond_spend()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_left integer;
  v_take integer;
  v_lot public.lifetime_vip_diamond_lots%ROWTYPE;
  v_expiry jsonb;
BEGIN
  IF NEW.amount >= 0
     OR NEW.user_id IS NULL
     OR COALESCE(NEW.reference_id, '') LIKE 'lifetime-vip-expiry:%'
  THEN
    RETURN NEW;
  END IF;

  v_expiry := public.expire_lifetime_vip_diamond_lots_for_user(
    NEW.user_id,
    COALESCE(NEW.created_at, now())
  );
  IF COALESCE((v_expiry ->> 'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Lifetime VIP Diamond expiry failed before spend allocation: %',
      COALESCE(v_expiry ->> 'error', 'unknown_error');
  END IF;

  v_left := (-NEW.amount)::integer;
  FOR v_lot IN
    SELECT *
      FROM public.lifetime_vip_diamond_lots
     WHERE user_id = NEW.user_id
       AND status = 'active'
       AND remaining_amount > 0
       AND expires_at > COALESCE(NEW.created_at, now())
     ORDER BY expires_at, issued_at, id
     FOR UPDATE
  LOOP
    EXIT WHEN v_left <= 0;
    v_take := LEAST(v_left, v_lot.remaining_amount);
    INSERT INTO public.lifetime_vip_diamond_lot_allocations(
      transaction_id, lot_id, user_id, amount
    ) VALUES (NEW.id, v_lot.id, NEW.user_id, v_take);
    UPDATE public.lifetime_vip_diamond_lots
       SET remaining_amount = remaining_amount - v_take,
           consumed_amount = consumed_amount + v_take,
           status = CASE WHEN remaining_amount - v_take = 0 THEN 'exhausted' ELSE status END,
           updated_at = now()
     WHERE id = v_lot.id;
    v_left := v_left - v_take;
  END LOOP;
  RETURN NEW;
END;
$function$

expire_lifetime_vip_diamond_lots_for_use.definition:
CREATE OR REPLACE FUNCTION public.expire_lifetime_vip_diamond_lots_for_user(p_user_id uuid, p_as_of timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_lot public.lifetime_vip_diamond_lots%ROWTYPE;
  v_burn_result jsonb;
  v_tx uuid;
  v_expired integer := 0;
BEGIN
  IF p_user_id IS NULL OR p_as_of IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
  END IF;

  -- The profile lock serializes expiry against every canonical wallet writer.
  PERFORM 1 FROM public.profiles WHERE id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'profile_not_found');
  END IF;

  FOR v_lot IN
    SELECT *
      FROM public.lifetime_vip_diamond_lots
     WHERE user_id = p_user_id
       AND status = 'active'
       AND remaining_amount > 0
       AND expires_at <= p_as_of
     ORDER BY expires_at, issued_at, id
     FOR UPDATE
  LOOP
    v_burn_result := public.fn_ca_burn(
      'diamonds',
      'player',
      p_user_id,
      v_lot.remaining_amount,
      'Expired Lifetime VIP Monthly Diamonds',
      'lifetime-vip-expiry:' || v_lot.id::text,
      'promotional'
    );
    IF COALESCE((v_burn_result ->> 'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Lifetime VIP Diamond expiry burn refused: %',
        COALESCE(v_burn_result ->> 'reason', 'unknown_error');
    END IF;

    SELECT id INTO v_tx
      FROM public.diamond_transactions
     WHERE user_id = p_user_id
       AND reference_id = 'lifetime-vip-expiry:' || v_lot.id::text
     LIMIT 1;
    IF v_tx IS NULL THEN
      RAISE EXCEPTION 'Lifetime VIP Diamond expiry has no journal receipt';
    END IF;

    UPDATE public.lifetime_vip_diamond_lots
       SET expired_amount = expired_amount + remaining_amount,
           remaining_amount = 0,
           status = 'expired',
           expiry_transaction_id = v_tx,
           updated_at = now()
     WHERE id = v_lot.id;
    v_expired := v_expired + v_lot.remaining_amount;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', p_user_id,
    'expired', v_expired
  );
END;
$function$

fn_ca_burn.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_burn(p_asset text, p_source text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text DEFAULT 'admin'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_house constant uuid := '00000000-0000-0000-0000-00000000d1a0';
  v_actor uuid := auth.uid();
  v_admin boolean := false;
  v_asset text := lower(btrim(COALESCE(p_asset, '')));
  v_src   text := lower(btrim(COALESCE(p_source, '')));
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_class text := lower(btrim(COALESCE(p_class, 'admin')));
  v_holder uuid;
  v_prior jsonb; v_before numeric; v_after numeric; v_label text;
  v_supply numeric; v_chip_id uuid; v_dia_id uuid; v_actorlb text; v_result jsonb;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT EXISTS (SELECT 1 FROM public.profiles p
                    WHERE p.id = v_actor AND p.role IN ('admin', 'god')) INTO v_admin;
    IF NOT v_admin THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'the_mint_is_admin_only');
    END IF;
  END IF;

  IF v_asset NOT IN ('chips', 'diamonds') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'asset_must_be_chips_or_diamonds');
  END IF;
  IF v_asset = 'chips' AND v_src NOT IN ('club', 'union') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'chips_are_retired_from_a_club_or_union_wallet_only');
  END IF;
  IF v_asset = 'diamonds' AND v_src NOT IN ('player', 'house') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamonds_are_retired_from_a_player_or_from_the_house_only');
  END IF;
  IF v_class NOT IN ('purchased', 'promotional', 'earned', 'transferred', 'seeded',
                     'refund', 'spend', 'bridge', 'deletion', 'admin', 'arena',
                     'house', 'unknown') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unknown_issuance_class', 'class', v_class);
  END IF;
  IF v_asset = 'diamonds' AND v_src = 'house' THEN
    IF p_target_id IS NOT NULL AND p_target_id <> c_house THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'the_house_target_is_the_house_sentinel_or_null');
    END IF;
  ELSIF p_target_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'target_required');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive_to_two_decimals');
  END IF;
  IF v_asset = 'diamonds' AND p_amount <> round(p_amount, 0) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamonds_are_whole_numbers');
  END IF;
  IF length(v_reason) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'retirement_needs_a_real_reason');
  END IF;
  IF COALESCE(btrim(p_op_id), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'idempotency_key_required');
  END IF;

  SELECT result INTO v_prior FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_ca_burn';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims WHERE op_id = p_op_id AND fn_name = 'fn_ca_burn';
  END IF;
  INSERT INTO public.ca_op_claims (op_id, fn_name, claimed_by)
  VALUES (p_op_id, 'fn_ca_burn', v_actor);

  PERFORM pg_advisory_xact_lock(hashtext('ca_mint_ledger:' || v_asset));

  IF v_asset = 'diamonds' THEN
    IF v_src = 'house' THEN
      INSERT INTO public.ca_diamond_house (id, balance)
      VALUES (1, 0) ON CONFLICT (id) DO NOTHING;
      SELECT COALESCE(balance, 0) INTO v_before
        FROM public.ca_diamond_house WHERE id = 1 FOR UPDATE;
      IF v_before < p_amount THEN
        RETURN public.fn_ca_release_claim('fn_ca_burn', p_op_id,
                 jsonb_build_object('ok', false, 'reason', 'that_would_take_the_house_below_zero',
                                  'balance', v_before, 'requested', p_amount));
      END IF;
      UPDATE public.ca_diamond_house
         SET balance = COALESCE(balance, 0) - p_amount, updated_at = now()
       WHERE id = 1 RETURNING balance INTO v_after;
      v_label  := 'the house';
      v_holder := c_house;
    ELSE
      SELECT COALESCE(diamonds, 0), COALESCE(NULLIF(btrim(username), ''), full_name, id::text)
        INTO v_before, v_label FROM public.profiles WHERE id = p_target_id FOR UPDATE;
      IF NOT FOUND THEN
        RETURN public.fn_ca_release_claim('fn_ca_burn', p_op_id,
                 jsonb_build_object('ok', false, 'reason', 'player_not_found'));
      END IF;
      IF v_before < p_amount THEN
        RETURN public.fn_ca_release_claim('fn_ca_burn', p_op_id,
                 jsonb_build_object('ok', false, 'reason', 'that_would_take_the_balance_below_zero',
                                  'balance', v_before, 'requested', p_amount));
      END IF;
      UPDATE public.profiles SET diamonds = COALESCE(diamonds, 0) - p_amount
       WHERE id = p_target_id RETURNING diamonds INTO v_after;
      -- The op id is the journal reference (DR4), the same way fn_ca_mint records it.
      INSERT INTO public.diamond_transactions
        (user_id, type, transaction_type, amount, balance_after, description, source,
         metadata, counterparty, issuance_class, reference_id)
      VALUES (p_target_id, 'spend', 'burn', -p_amount, v_after,
              'The Mint (retired): ' || v_reason, 'the_mint',
              jsonb_build_object('burned_by', v_actor, 'op_id', p_op_id),
              'retired', v_class, p_op_id)
      RETURNING id INTO v_dia_id;
      v_holder := p_target_id;
    END IF;
  ELSE
    -- The leg is declared WITH A KEY and found by that key: never by shape.
    PERFORM public.fn_ca_declare_ledger('burn', 'chip_retirement', NULL, NULL, 'burn:' || p_op_id, NULL);
    IF v_src = 'club' THEN
      SELECT COALESCE(chip_treasury, 0), name INTO v_before, v_label
        FROM public.clubs WHERE id = p_target_id FOR UPDATE;
      IF NOT FOUND THEN
        RETURN public.fn_ca_release_claim('fn_ca_burn', p_op_id,
                 jsonb_build_object('ok', false, 'reason', 'club_not_found'));
      END IF;
      IF v_before < p_amount THEN
        RETURN public.fn_ca_release_claim('fn_ca_burn', p_op_id,
                 jsonb_build_object('ok', false, 'reason', 'that_would_take_the_treasury_below_zero',
                                  'balance', v_before, 'requested', p_amount));
      END IF;
      UPDATE public.clubs SET chip_treasury = COALESCE(chip_treasury, 0) - p_amount
       WHERE id = p_target_id RETURNING chip_treasury INTO v_after;
      INSERT INTO public.chip_transactions
        (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after)
      VALUES (p_target_id, v_actor, NULL, p_amount, 'treasury_burn',
              'The Mint (retired): ' || v_reason, v_after);
    ELSE
      SELECT COALESCE(w.chip_balance, 0), u.name INTO v_before, v_label
        FROM public.union_wallets w JOIN public.unions u ON u.id = w.union_id
       WHERE w.union_id = p_target_id FOR UPDATE OF w;
      IF NOT FOUND THEN
        RETURN public.fn_ca_release_claim('fn_ca_burn', p_op_id,
                 jsonb_build_object('ok', false, 'reason', 'union_wallet_not_found'));
      END IF;
      IF v_before < p_amount THEN
        RETURN public.fn_ca_release_claim('fn_ca_burn', p_op_id,
                 jsonb_build_object('ok', false, 'reason', 'that_would_take_the_union_bank_below_zero',
                                  'balance', v_before, 'requested', p_amount));
      END IF;
      UPDATE public.union_wallets
         SET chip_balance = COALESCE(chip_balance, 0) - p_amount, updated_at = now()
       WHERE union_id = p_target_id RETURNING chip_balance INTO v_after;
    END IF;
    SELECT id INTO v_chip_id FROM public.chip_ledger WHERE idempotency_key = 'burn:' || p_op_id;
    PERFORM set_config('app.ledger_category', '', true);
    PERFORM set_config('app.ledger_counterparty', '', true);
    PERFORM set_config('app.ledger_counterparty_entity', '', true);
    PERFORM set_config('app.ledger_idempotency_key', '', true);
    IF v_chip_id IS NULL THEN
      RAISE EXCEPTION 'fn_ca_burn: the balance moved but no journal leg was written for key burn:% - refusing to register a retirement the journal does not carry', p_op_id;
    END IF;
    v_holder := p_target_id;
  END IF;

  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) - p_amount
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = v_asset;
  SELECT COALESCE(NULLIF(btrim(username), ''), full_name, id::text)
    INTO v_actorlb FROM public.profiles WHERE id = v_actor;

  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason,
     performed_by, performed_by_label, chip_ledger_id, diamond_tx_id)
  VALUES
    (p_op_id, 'burn', v_asset, v_src, v_holder, v_label, p_amount,
     v_before, v_after, v_supply, v_reason, v_actor, v_actorlb, v_chip_id, v_dia_id);

  v_result := jsonb_build_object(
    'ok', true, 'replayed', false, 'action', 'burn',
    'asset', v_asset, 'source', v_src, 'issuance_class', v_class,
    'target_id', v_holder, 'target_label', v_label, 'amount', p_amount,
    'balance_before', v_before, 'balance_after', v_after, 'supply_after', v_supply,
    'ledger_id', v_chip_id,
    'burned_by', v_actor, 'reason', v_reason, 'op_id', p_op_id);

  UPDATE public.ca_op_claims SET result = v_result, finalized_at = now()
   WHERE op_id = p_op_id AND fn_name = 'fn_ca_burn';

  RETURN v_result;
END;
$function$
